private static String encodeTimelineCursor(String sessionId, long beforeSequence, long generation) {
    String raw = String.join("\n", "v1", "session-timeline", "sequence-desc",
            java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(
                    sessionId.getBytes(StandardCharsets.UTF_8)),
            Long.toString(beforeSequence), Long.toString(generation));
    return java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
}

private static TimelineCursor decodeTimelineCursor(String cursor, String sessionId) {
    try {
        String raw = new String(java.util.Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
        String[] parts = raw.split("\n", -1);
        String boundSession = java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(
                sessionId.getBytes(StandardCharsets.UTF_8));
        if (parts.length != 6 || !"v1".equals(parts[0]) || !"session-timeline".equals(parts[1])
                || !"sequence-desc".equals(parts[2]) || !boundSession.equals(parts[3])) {
            throw new IllegalArgumentException("invalid timeline cursor");
        }
        long sequence = Long.parseLong(parts[4]);
        long generation = Long.parseLong(parts[5]);
        if (sequence < 1 || generation < 1) throw new IllegalArgumentException("invalid timeline cursor");
        return new TimelineCursor(sequence, generation);
    } catch (RuntimeException failure) {
        throw invalidCursor("malformed", failure);
    }
}

